import app from 'flarum/admin/app';
const order = ['claude', 'openai', 'ollama', 'deepl', 'google'];
export const RECOMMENDED_DRIVER = 'claude';
export const AI_DRIVERS = ['claude', 'openai', 'ollama'];

/**
 * Drivers from the admin payload, the recommended one first, then the
 * bundled ones, then third-party drivers alphabetically.
 */
export function drivers() {
  const payload = app.data['fof-translate.drivers'] ?? {};
  return Object.values(payload).filter(driver => !!driver && typeof driver.name === 'string').sort((a, b) => {
    const ia = order.indexOf(a.name);
    const ib = order.indexOf(b.name);
    if (ia !== -1 || ib !== -1) return (ia === -1 ? Infinity : ia) - (ib === -1 ? Infinity : ib);
    return a.name.localeCompare(b.name);
  });
}
export function findDriver(name) {
  return name ? drivers().find(driver => driver.name === name) : undefined;
}
flarum.reg.add('fof-translate', 'admin/components/drivers', { RECOMMENDED_DRIVER: RECOMMENDED_DRIVER,AI_DRIVERS: AI_DRIVERS,drivers: drivers,findDriver: findDriver, });